import os,re,json,collections,glob
plain_re=re.compile(r'^(\S+)\s+(\S+)\s+\[([^\]]+)\]\s?(.*)$')
errs=collections.Counter(); users=collections.Counter(); db=[]; over=[]; events=collections.Counter(); levels_by_svc=collections.defaultdict(collections.Counter)
for f in sorted(glob.glob('logs/*')):
    for i,line in enumerate(open(f),1):
        s=line.rstrip('\n')
        if f.endswith('.jsonl'):
            o=json.loads(s); ts=o['ts']; lvl=o['level']; svc=o['service']; msg=o['msg']
        else:
            m=plain_re.match(s); ts,lvl,svc,msg=m.groups()
        levels_by_svc[svc][lvl]+=1
        if lvl=='ERROR': errs[svc]+=1
        if svc=='auth' and lvl=='WARN' and 'login failed' in msg:
            mm=re.search(r'login failed user=(\S+)',msg)
            users[mm.group(1)]+=1
        if 'db timeout' in msg:
            db.append((ts,svc,lvl,msg,f,i))
        if 'request done' in msg:
            mm=re.search(r'latency_ms=(\d+)',msg)
            if mm and int(mm.group(1))>2000: over.append((ts,svc,int(mm.group(1)),f,i))
print('error counts',errs)
print('levels by svc')
for svc in sorted(levels_by_svc): print(svc,dict(levels_by_svc[svc]))
print('auth warn users',users, 'total',sum(users.values()))
print('db timeout count',len(db))
for x in sorted(db)[:10]: print(x)
print('over count',len(over))
print('earliest overall timestamps?', )
PY"}

