import glob,json,re
from collections import Counter
plain_re = re.compile(r'^(\S+)\s+(\S+)\s+\[([^\]]+)\]\s?(.*)$')
error_counts=Counter(); failed_logins=Counter(); db_timeouts=[]; over_2000=0
for path in sorted(glob.glob('logs/*')):
    for line in open(path, encoding='utf-8'):
        line=line.rstrip('\n')
        if path.endswith('.jsonl'):
            rec=json.loads(line); ts,level,service,msg=rec['ts'],rec['level'],rec['service'],rec['msg']
        else:
            ts,level,service,msg=plain_re.match(line).groups()
        if level=='ERROR': error_counts[service]+=1
        if service=='auth' and level=='WARN' and 'login failed' in msg:
            failed_logins[re.search(r'login failed user=(\S+)',msg).group(1)]+=1
        if 'db timeout' in msg: db_timeouts.append(ts)
        if 'request done' in msg:
            lm=re.search(r'latency_ms=(\d+)',msg)
            if int(lm.group(1))>2000: over_2000+=1
print(error_counts)
print(failed_logins)
print(len(db_timeouts),min(db_timeouts))
print(over_2000)
PY"}

